import { type Page, type Locator } from '@playwright/test';

export class CheckoutPage {
  readonly submitBtn: Locator;
  constructor(page: Page) {
    this.submitBtn = page.getByRole('button', { name: 'Submit' });
  }
  async navigate() { await this.page.goto('/checkout'); }
  async submit() { await this.submitBtn.click(); }
}

import { type Page, type Locator } from '@playwright/test';

export class CheckoutPage {
  readonly emailInput: Locator;
  constructor(page: Page) {
    this.emailInput = page.getByTestId('checkout-email');
  }
  async fillEmail(email: string) { await this.emailInput.fill(email); }
}

import { type Page, type Locator } from '@playwright/test';

export class LoginPage {
  readonly emailInput: Locator;
  constructor(page: Page) {
    this.emailInput = page.getByLabel('Email address');
  }
  async fillEmail(email: string) { await this.emailInput.fill(email); }
}

import { type Page, type Locator } from '@playwright/test';

export class HeaderPage {
  readonly accountLink: Locator;
  constructor(page: Page) {
    this.accountLink = page.getByRole('link', { name: 'My Account' });
  }
  async goToAccount() { await this.accountLink.click(); }
}

import { type Page, type Locator } from '@playwright/test';

export class CartPage {
  readonly heading: Locator;
  constructor(page: Page) {
    this.heading = page.getByRole('heading', { name: 'Shopping Cart' });
  }
  async waitForPage() { await this.heading.waitFor(); }
}

import { type Page, type Locator } from '@playwright/test';

export class CheckoutPage {
  readonly termsCheckbox: Locator;
  constructor(page: Page) {
    this.termsCheckbox = page.getByRole('checkbox', { name: 'I agree to terms' });
  }
  async acceptTerms() { await this.termsCheckbox.check(); }
}

import { type Page, type Locator } from '@playwright/test';

export class SearchPage {
  readonly searchInput: Locator;
  constructor(page: Page) {
    this.searchInput = page.getByPlaceholder('Search products...');
  }
  async search(query: string) { await this.searchInput.fill(query); }
}

import { type Page, type Locator } from '@playwright/test';

export class ProductsPage {
  readonly sortSelect: Locator;
  constructor(page: Page) {
    this.sortSelect = page.getByRole('combobox', { name: 'Sort By' });
  }
  async sortBy(value: string) { await this.sortSelect.selectOption(value); }
}

import { type Page, type Locator } from '@playwright/test';

export class ProductsPage {
  readonly productImage: Locator;
  constructor(page: Page) {
    this.productImage = page.getByAltText('Product thumbnail');
  }
  async clickImage() { await this.productImage.click(); }
}

import { type Page, type Locator } from '@playwright/test';

export class CartPage {
  readonly removeItemBtn: Locator;
  constructor(page: Page) {
    this.removeItemBtn = page.getByRole('button', { name: 'Remove item' });
  }
  async removeItem() { await this.removeItemBtn.click(); }
}
